from shelfkit.store import Store
from shelfkit.models import Book
def mk(n, cat='x'):
    s = Store()
    for k in range(n):
        s.add(Book(id='k%02d' % k, name='N%02d' % k, genre=cat, qty=(k * 5) % 7, price=1.0 + k))
    return s
from shelfkit.errors import Invalid
try:
    mk(0).add(Book(id='a', name='b', genre='c', qty=-1))
except Invalid as e:
    print(e)

